from fastapi.sse import ServerSentEvent, format_sse_event
import pytest

def test_sse_event_newlines():
    # This should currently pass (no error) but should fail after the fix
    try:
        ServerSentEvent(event="foo\nbar")
        print("ServerSentEvent(event='foo\\nbar') succeeded")
    except ValueError as e:
        print(f"ServerSentEvent(event='foo\\nbar') failed: {e}")

    try:
        ServerSentEvent(id="foo\nbar")
        print("ServerSentEvent(id='foo\\nbar') succeeded")
    except ValueError as e:
        print(f"ServerSentEvent(id='foo\\nbar') failed: {e}")

def test_format_sse_event_newlines():
    # This should currently pass (no error) but should fail after the fix
    try:
        format_sse_event(event="foo\nbar", data_str="data")
        print("format_sse_event(event='foo\\nbar') succeeded")
    except ValueError as e:
        print(f"format_sse_event(event='foo\\nbar') failed: {e}")

    try:
        format_sse_event(id="foo\nbar", data_str="data")
        print("format_sse_event(id='foo\\nbar') succeeded")
    except ValueError as e:
        print(f"format_sse_event(id='foo\\nbar') failed: {e}")

if __name__ == "__main__":
    test_sse_event_newlines()
    test_format_sse_event_newlines()

